Map<String, double> calculateAverageProfit(List<Transaction> transactions) {
  Map<String, double> result = {};

  for (Transaction transaction in transactions) {
    String coinName = transaction.coinName;
    double profit = transaction.profit;

    if (result[coinName] == null) {
      result[coinName] = profit;
    } else {
      result[coinName] += profit;
    }
  }

  return result.map((key, value) => MapEntry(key, value / transactions.length));
}

