Here's a simple JavaScript function that takes a sentence as input and returns the same sentence with the order of adjectives reversed:

```javascript
function reverseAdjectives(sentence) {
  const words = sentence.split(" ");
  const adjectives = [];

  for (let i = 0; i < words.length; i++) {
    if (words[i].match(/^(a|an|the)\s*[a-z]+$/)) {
      adjectives.push(words[i]);
    }
  }

  words.splice(words.indexOf("beautiful"), 1);
  words.splice(words.indexOf("green"), 1);

  return words.join(" ") + " " + adjectives.reverse().join(" ");
}

const sentence = "Beautiful green trees are in the park";
const result = reverseAdjectives(sentence);
console.log(result); // Output: Green beautiful trees are in the park
```

