#include <iostream>
#include <string>
#include <sstream>
#include <vector>

using namespace std;

int fibonacci(int n, int a, int b) {
    if (n == 1) {
        return a;
    } else if (n == 2) {
        return b;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    string input;
    vector<int> sequence;
    int numElements, a, b;

    cout << "Enter the first two integers: ";
    getline(cin, input);
    istringstream iss(input);

    if (!(iss >> a >> b)) {
        cout << "Invalid input. Please enter two integers." << endl;
        return 1;
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> numElements;

    if (numElements <= 0) {
        cout << "Invalid input. Please enter a positive integer." << endl;
        return 1;
    }

    for (int i = 3; i <= numElements; i++) {
        sequence.push_back(fibonacci(i, a, b));
        a = b;
        b = sequence[i - 1];
    }

    cout << "Fibonacci sequence: ";
    for (int i = 0; i < sequence.size(); i++) {
        cout << sequence[i] << ", ";
    }
    cout << endl;

    return 0;
}
```

