Here's a MATLAB code that identifies the tense used in a given sentence:

```matlab
function tense = identify_tense(sentence)
    % Split the sentence into words
    words = split(sentence);

    % Initialize the tense variable
    tense = 'unknown';

    % Check for common tense markers
    if strcmp(words{end}, 'ly') || strcmp(words{end}, 'ing') || strcmp(words{end}, 'ed')
        % Check for present tense
        if strcmp(words{end - 1}, 'be') && strcmp(words{end - 2}, 'ing')
            tense = 'present';
        % Check for past tense
        elseif strcmp(words{end - 1}, 'be') && strcmp(words{end - 2}, 'ed')
            tense = 'past';
        % Check for future tense
        elseif strcmp(words{end - 1}, 'will') || strcmp(words{end - 1}, 'shall') || strcmp(words{end - 1}, 'going')
            tense = 'future';
        % Check for present perfect tense
        elseif strcmp(words{end - 1}, 'have') && strcmp(words{end - 2}, 'been') && strcmp(words{end - 3}, 'ing')
            tense = 'present_perfect';
        % Check for past perfect tense
        elseif strcmp(words{end - 1}, 'have') && strcmp(words{end - 2}, 'been') && strcmp(words{end - 3}, 'ed')
            tense = 'past_perfect';
        % Check for future perfect tense
        elseif strcmp(words{end - 1}, 'will') || strcmp(words{end - 1}, 'shall') || strcmp(words{end - 1}, 'going') && strcmp(words{end - 2}, 'have') && strcmp(words{end - 3}, 'been') && strcmp(words{end - 4}, 'ing')
            tense = 'future_perfect';
    end

    % Return the identified tense
    return tense

Here's an example of a generic REST service wrapper class in C# that includes auth token handling:
```csharp
using System;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;
using System.Text;

public class RestServiceWrapper<T>
{
    private readonly string _baseAddress;
    private readonly string _authToken;

    public RestServiceWrapper(string baseAddress, string authToken)
    {
        _baseAddress = baseAddress;
        _authToken = authToken;
    }

    public async Task<T> GetAsync(string endpoint)
    {
        using (var client = new HttpClient())
        {
            client.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", _authToken);
            var response = await client.GetAsync($"{_baseAddress}/{endpoint}");
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsAsync<T>();
        }
    }

    public async Task<T> PostAsync(string endpoint, object data)
    {
        using (var client = new HttpClient())
        {
            client.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", _authToken);
            var content = new StringContent(JsonConvert.SerializeObject(data), Encoding.UTF8, "application/json");
            var response = await client.PostAsync($"{_baseAddress}/{endpoint}", content);
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsAsync<T>();
        }
    }
}
```
