```javascript
function searchPlace() {
  var sheet = SpreadsheetApp.getActiveSheet();
  var dataRange = sheet.getRange("A2:A"); // Assuming your place names are in column A starting from row 2
  var places = dataRange.getValues().flat(); // Flatten the 2D array into a 1D array

  var geocoder = new google.maps.Geocoder();
  var results = [];

  for (var i = 0; i < places.length; i++) {
    var place = places[i];
    geocoder.geocode({ address: place }, function(results, status) {
      if (status == google.maps.GeocoderStatus.OK) {
        var lat = results[0].geometry.location.lat();
        var lng = results[0].geometry.location.lng();
        results.push([place, lat, lng]);
      } else {
        results.push([place, "Error: " + status]);
      }
    });
  }

  sheet.getRange("B2:C").setValues(results); // Assume you want to store the latitude and longitude in columns B and C respectively, starting from row 2
}
```

This script will search for each place name in the specified range, geocode it using the Google Maps Geocoder API, and store the latitude and longitude in the corresponding columns. Note that you'll need to enable the Google Maps API in your Google Cloud Platform project and get an API key before running this script.

Here's a PHP custom function "smart_sort_array" that meets your requirements:

```php
function smart_sort_array($set, $order) {
    usort($set, function ($a, $b) use ($order) {
        return $order === 'asc' ? strnatcmp($a['age'], $b['age']) : strnatcmp($b['age'], $a['age']);
    });

    return $set;
}
```

