Here's a JavaScript function that takes a string variable in dot notation and returns all entries in an object where the nested key value matches the string key:

```javascript
function getEntries(object, key) {
  const entries = [];

  Object.keys(object).forEach(key => {
    if (key === key) {
      entries.push(object[key]);
    } else {
      const nestedObject = object[key];
      getEntries(nestedObject, key);
    }
  });

  return entries;
}

const myObject = {
  key1: 'value1',
  key2: {
    nestedKey1: 'nestedValue1',
    nestedKey2: 'nestedValue2',
  },
};

