```php
<?php
// Connect to the SQL database
$servername = "localhost";
$username = "username";
$password = "password";
$dbname = "burger_joint";

$conn = new mysqli($servername, $username, $password, $dbname);

// Check connection
if ($conn->connect_error) {
    die("Connection failed: " . $conn->connect_error);
}

// Retrieve menu data
$sql = "SELECT * FROM burgers JOIN sides ON burgers.id = sides.burger_id JOIN drinks ON burgers.id = drinks.burger_id ORDER BY name ASC";
$result = $conn->query($sql);

// Display menu data on the HTML page
echo "<ul>";
while ($row = $result->fetch_assoc()) {
    echo "<li>" . $row["name"] . " - $" . $row["price"] . "</li>";
}
echo "</ul>";

// Close connection
$conn->close();
?>
