Here's a simple decorator for Nest.js middleware that checks the NODE_ENV variable and calls `next()` if it's equal to 'true', otherwise it returns `false`.

```typescript
import { Injectable, CanActivate, ExecutionContext } from '@nestjs/common';

@Injectable()
export class EnvMiddleware implements CanActivate {
  canActivate(context: ExecutionContext): boolean {
    const request = context.switchToHttp().getRequest();
    const env = process.env.NODE_ENV;

    if (env === 'true') {
      return true;
    }

    return false;
  }
}
```

You can use this decorator in your Nest.js controller like this:

```typescript
import { Controller, Get } from '@nestjs/common';
import { EnvMiddleware } from './env.middleware';

@Controller('api')
export class MyController {
  constructor(private readonly envMiddleware: EnvMiddleware) {}

  @Get()
  async getData(): Promise<any> {
    await this.envMiddleware.canActivate(new ExecutionContext());
    // Your code here
  }
}
```

In this example, the `getData` method will only be executed if the NODE_ENV variable is set to 'true'. Otherwise, it will return `false`.

