import re
from decimal import Decimal

def english_number(n, lang='en'):
    if lang not in ['en', 'fr', 'es', 'de']:
        raise ValueError('Invalid language')

    if isinstance(n, str):
        n = float(n)

    if n < 0:
        return f'minus {english_number(-n, lang)}'

    words = []
    if n == 0:
        words.append('zero')
    elif n > 0:
        words.append(str(int(n)))
        while n >= 1000:
            words.append(english_number(n // 1000, lang)[-1])
            n -= 1000 * int(english_number(n // 1000, lang)[-1])

    if len(words) > 1:
        return ' '.join(reversed(words))
    else:
