Here's the code for the `redis.js` file:

```javascript
const { Redis } = require('ioredis');

class RedisClient {
  constructor() {
    this.client = new Redis({
      host: 'localhost',
      port: 6379,
      db: 0,
    });

    this.client.on('error', (err) => {
      console.error('Error with Redis client:', err);
    });
  }

  isAlive() {
    return this.client.ping().then((result) => result === 'PONG');
  }

  async get(key) {
    try {
      const value = await this.client.get(key);
      return value;
    } catch (err) {
      console.error('Error getting from Redis:', err);
      throw err;
    }
  }

  async set(key, value, duration) {
    try {
      await this.client.setex(key, duration, value);
    } catch (err) {
      console.error('Error setting in Redis:', err);
      throw err;
    }
  }

  async del(key) {
    try {
      await this.client.del(key);
    } catch (err) {
      console.error('Error deleting from Redis:', err);
      throw err;
    }
  }
}

const redisClient = new RedisClient();

module.exports = redisClient;
```

This code defines a `RedisClient` class with methods for connecting to Redis, checking if the connection is alive, getting and setting values, and deleting keys. It also exports an instance of the `RedisClient` class called `redisClient`.

