# Function to check if an SID is present in the SIDHistory of a user or group in the domain
function CheckSIDInSIDHistory($sid) {
    $domain = Get-ADDomain -Filter {Name -eq $domainName}
    $users = Get-ADUser -Filter {(MemberOf -like "*$domainName*") -and (SIDHistory -like "*$sid*")}
    $groups = Get-ADGroup -Filter {(MemberOf -like "*$domainName*") -and (SIDHistory -like "*$sid*")}

    if ($users.Count -gt 0) {
        return True
    }

    if ($groups.Count -gt 0) {
        return True
    }

    return False
}

